    /// Parses the absolute `M x y`, `L x y` and `Z` commands these files use.
    static func path(_ d: String) -> Path {
        var p = Path()
        var command: Character = "M"
        var numbers: [Double] = []
        func flush() {
            guard numbers.count >= 2 else { return }
            var i = 0
            while i + 1 < numbers.count {
                let pt = CGPoint(x: numbers[i], y: numbers[i + 1])
                if command == "M" && i == 0 { p.move(to: pt) } else { p.addLine(to: pt) }
                i += 2
            }
            numbers.removeAll()
        }
        var token = ""
        func endToken() { if let v = Double(token) { numbers.append(v) }; token = "" }
        for ch in d {
            switch ch {
            case "M", "L", "Z":
                endToken(); flush()
                if ch == "Z" { p.closeSubpath() } else { command = ch }
            case " ", ",": endToken()
            case "-": endToken(); token = "-"
            default: token.append(ch)
            }
        }
        endToken(); flush()
        return p
    }
